export const TOTAL_DEX_COUNT = RARITIES.length + BABY_DEX.length + YOUTH_DEX.length + ADULT_PETS.length;

// --- 輔助函數 ---
export const rollGacha = () => {
  const rand = Math.random();
  let cumulative = 0;
  for (let r of RARITIES) {
    cumulative += r.chance;
    if (rand <= cumulative) return r;
  }
  return RARITIES[0];
};

export const shuffleArray = (array) => {
  const newArr = [...array];
  for (let i = newArr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
  }
  return newArr;
};
